import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { readFile, mkdir, readdir, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { collectFixture } from './braude-roster-fixture.mjs';

// Synthetic export generated by tests/test_braude_academic.py; never personal data.
const XLSX = Buffer.from('', 'base64');
const runtimeDir = resolve('../../.runtime/roster-collector');
const accountId = '00000000-0000-4000-8000-000000000025';
const escape = value => value.replaceAll('&', '&amp;').replaceAll('"', '&quot;');

async function scenario(mode, run) {
  const server = createServer((request, response) => {
    const path = new URL(request.url, 'http://fixture.invalid').pathname;
    if (path === '/report') {
      if (mode === 'redirect') { response.writeHead(302, { Location: 'https://example.invalid/' }); return response.end(); }
      if (mode === 'login') return response.end('<p data-lifeos-login-required>Sign in</p>');
      const source = {account_id: mode === 'owner' ? 'other-owner' : accountId,
        observed_at: mode === 'metadata' ? 'not-a-date' : new Date().toISOString(),
        year:2027, semester:1, start_date:'2026-10-02', end_date:'2027-01-30', complete:true};
      response.setHeader('Content-Type', 'text/html; charset=utf-8');
      return response.end(`<main data-lifeos-fixture="true" data-lifeos-roster-source="${escape(JSON.stringify(source))}">Fixture only</main>${mode === 'missing' ? '' : `<a data-testid="roster-export" download="untrusted-name.xlsx" href="${mode === 'unsafe' ? 'https://example.invalid/roster.xlsx' : '/roster.xlsx'}">ייצוא קורסים</a>`}`);
    }
    if (path === '/roster.xlsx') {
      if (mode === 'timeout') { response.writeHead(200); response.flushHeaders(); return; }
      if (mode === 'failed') { response.writeHead(500); return response.end('failed'); }
      if (mode === 'export-redirect') { response.writeHead(302, {Location:'https://example.invalid/file.xlsx'}); return response.end(); }
      if (mode === 'chunked') {
        response.writeHead(200, {'Content-Type':'application/octet-stream'});
        response.write(Buffer.alloc(4 * 1024 * 1024)); return response.end(Buffer.alloc(1));
      }
      const body = mode === 'oversize' ? Buffer.alloc(4 * 1024 * 1024 + 1) : XLSX;
      response.writeHead(200, {'Content-Type':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'Content-Disposition':'attachment; filename="../../untrusted.xlsx"', 'Content-Length':body.length});
      return response.end(body);
    }
    response.writeHead(404); response.end();
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const url = `http://127.0.0.1:${server.address().port}/report`;
  try { await run(url); } finally { await new Promise(resolve => server.close(resolve)); }
}

test('collects synthetic export and closes ephemeral browser', async () => {
  await scenario('valid', async url => {
    const result = await collectFixture({url, accountId, runtimeDir});
    assert.equal(result.status, 'ready');
    assert.equal(result.fixture, true);
    assert.deepEqual(Buffer.from(result.export_base64, 'base64'), XLSX);
    assert.equal(result.source.account_id, accountId);
    await mkdir(runtimeDir, {recursive:true});
    await writeFile(resolve(runtimeDir, 'collected-fixture.json'), JSON.stringify(result));
    assert.equal(JSON.parse(await readFile(resolve(runtimeDir, 'collected-fixture.json'))).status, 'ready');
  });
});

for (const [mode, reason] of [['login','login_required'], ['owner','account_mismatch'],
  ['metadata','invalid_source'], ['missing','export_unavailable'], ['unsafe','unsafe_export'],
  ['failed','download_failed'], ['oversize','response_too_large'], ['redirect','redirect_rejected'],
  ['export-redirect','redirect_rejected'], ['chunked','response_too_large'], ['timeout','source_timeout']]) {
  test(`retains no export for ${mode}`, async () => {
    await scenario(mode, async url => {
      const result = await collectFixture({url, accountId, runtimeDir});
      assert.notEqual(result.status, 'ready');
      assert.equal(result.reason, reason);
      assert.equal(result.export_base64, undefined);
    });
  });
}

test('rejects real origins and non-runtime workspace paths before browser launch', async () => {
  assert.equal((await collectFixture({url:'https://info.braude.ac.il/report', accountId, runtimeDir})).reason, 'fixture_origin_required');
  assert.equal((await collectFixture({url:'http://127.0.0.1:8877/report', accountId, runtimeDir:resolve('../../docs')})).reason, 'runtime_directory_required');
});

test('fixture capture directories are removed after success and failures', async () => {
  assert.deepEqual((await readdir(runtimeDir)).filter(name => name.startsWith('capture-')), []);
});
